<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Carbon\Carbon;
class CalendarController extends Controller{
 public function index(Request $r){$p=$r->attributes->get('academic_period');abort_if(!$p,404);$u=$r->user();$from=Carbon::parse($r->input('from',now()->startOfWeek()->toDateString()));$to=$from->copy()->addDays(13);$q=DB::table('lesson_occurrences as l')->join('subjects as s','s.id','=','l.subject_id')->join('study_groups as g','g.id','=','l.study_group_id')->leftJoin('lesson_times as lt',fn($j)=>$j->on('lt.academic_period_id','=','l.academic_period_id')->on('lt.lesson_number','=','l.lesson_number'))->where('l.academic_period_id',$p->id)->whereBetween('l.lesson_date',[$from->toDateString(),$to->toDateString()])->where('l.status','!=','cancelled');if($u->teacher_id&&$u->hasRole('teacher'))$q->where('l.teacher_id',$u->teacher_id);elseif($u->student_id){$m=DB::table('student_group_memberships')->where('student_id',$u->student_id)->where('academic_period_id',$p->id)->first();$gid=$m?->study_group_id??DB::table('students')->where('id',$u->student_id)->value('current_group_id');$q->where('l.study_group_id',$gid);}elseif(!($u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('head_academic')))abort(403);$items=$q->select('l.id','l.lesson_date','l.lesson_number','l.homework','l.homework_due_at','s.name as subject_name','g.name as group_name','lt.starts_at')->orderBy('l.lesson_date')->orderBy('l.lesson_number')->get()->groupBy('lesson_date');return view('calendar.index',['items'=>$items,'from'=>$from,'to'=>$to]);}
 public function homework(Request $r){$p=$r->attributes->get('academic_period');$u=$r->user();abort_unless($u->teacher_id&&($u->hasRole('teacher')||$u->isSuperAdmin()||$u->hasRole('admin')),403);$status=$r->input('status','pending');$q=DB::table('homework_submissions as h')->join('lesson_occurrences as l','l.id','=','h.lesson_occurrence_id')->join('students as st','st.id','=','h.student_id')->join('subjects as s','s.id','=','l.subject_id')->join('study_groups as g','g.id','=','l.study_group_id')->where('l.academic_period_id',$p->id);if(!$u->isSuperAdmin()&&!$u->hasRole('admin'))$q->where('l.teacher_id',$u->teacher_id);if($status==='pending')$q->where('h.status','submitted');elseif(in_array($status,['checked','revision']))$q->where('h.status',$status);return view('homework.teacher',['items'=>$q->select('h.*','l.homework_due_at','l.id as lesson_id','st.last_name','st.first_name','s.name as subject_name','g.name as group_name')->orderByDesc('h.submitted_at')->get(),'status'=>$status]);}
}